package org.firstinspires.ftc.teamcode;

import com.pedropathing.math.Pose;

/**
 * Explicit BIOBUZZ field and robot-position presets.
 * Coordinate origin: inside Red/left + Audience/front corner.
 * +X points right toward Blue; +Y points back toward Scoring.
 * Heading 0 = right, 90 = back, 180 = left, 270 = front.
 *
 * No pose here is generated by reflecting or offsetting another pose.
 */
public final class FieldPoses {
    private FieldPoses() {}

    public enum Lane { OUTSIDE, INSIDE }
    public enum BypassSide { AUDIENCE, SCORING }

    public static final class FieldPoint {
        public final double x;
        public final double y;

        public FieldPoint(double x, double y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public String toString() {
            return String.format(java.util.Locale.US, "(%.3f, %.3f)", x, y);
        }
    }

    public enum Flower {
        RED_WALL("RED WALL / LEFT", new FieldPoint(2.630, 47.282),
                new Pose(19.000, 47.282, Math.toRadians(180))),
        SCORING_WALL("SCORING WALL / BACK", new FieldPoint(47.282, 138.718),
                new Pose(47.282, 122.348, Math.toRadians(90))),
        BLUE_WALL("BLUE WALL / RIGHT", new FieldPoint(138.718, 94.066),
                new Pose(122.348, 94.066, Math.toRadians(0))),
        AUDIENCE_WALL("AUDIENCE WALL / FRONT", new FieldPoint(94.066, 2.630),
                new Pose(94.066, 19.000, Math.toRadians(270)));

        public final String label;
        // Physical ring-bore center in field coordinates.
        public final FieldPoint center;
        // Robot-center stopping pose; this is not the physical Flower center.
        public final Pose robotStop;

        Flower(String label, FieldPoint center, Pose robotStop) {
            this.label = label;
            this.center = center;
            this.robotStop = robotStop;
        }
    }

    // Six manual starts per alliance. Row 1 is nearest Audience/front.
    // Robot is 18 x 18 in: side bumper flush to wall means center X=9 (Red)
    // or X=132.348 (Blue).
    private static final Pose[] RED_START_ROWS = {
            new Pose(9.000, 11.677, 0), new Pose(9.000, 35.016, 0),
            new Pose(9.000, 58.518, 0), new Pose(9.000, 82.020, 0),
            new Pose(9.000, 105.522, 0), new Pose(9.000, 129.266, 0)
    };
    private static final Pose[] BLUE_START_ROWS = {
            new Pose(132.348, 11.677, Math.PI), new Pose(132.348, 35.016, Math.PI),
            new Pose(132.348, 58.518, Math.PI), new Pose(132.348, 82.020, Math.PI),
            new Pose(132.348, 105.522, Math.PI), new Pose(132.348, 129.266, Math.PI)
    };

    // Explicit lane-entry poses for every start row.
    private static final Pose[] RED_OUTSIDE_LANE_ENTRY = {
            new Pose(18.000, 11.677, 0), new Pose(18.000, 35.016, 0),
            new Pose(18.000, 58.518, 0), new Pose(18.000, 82.020, 0),
            new Pose(18.000, 105.522, 0), new Pose(18.000, 129.266, 0)
    };
    private static final Pose[] RED_INSIDE_LANE_ENTRY = {
            new Pose(30.000, 11.677, 0), new Pose(30.000, 35.016, 0),
            new Pose(30.000, 58.518, 0), new Pose(30.000, 82.020, 0),
            new Pose(30.000, 105.522, 0), new Pose(30.000, 129.266, 0)
    };
    private static final Pose[] BLUE_OUTSIDE_LANE_ENTRY = {
            new Pose(123.348, 11.677, Math.PI), new Pose(123.348, 35.016, Math.PI),
            new Pose(123.348, 58.518, Math.PI), new Pose(123.348, 82.020, Math.PI),
            new Pose(123.348, 105.522, Math.PI), new Pose(123.348, 129.266, Math.PI)
    };
    private static final Pose[] BLUE_INSIDE_LANE_ENTRY = {
            new Pose(111.348, 11.677, Math.PI), new Pose(111.348, 35.016, Math.PI),
            new Pose(111.348, 58.518, Math.PI), new Pose(111.348, 82.020, Math.PI),
            new Pose(111.348, 105.522, Math.PI), new Pose(111.348, 129.266, Math.PI)
    };

    // Lane center waypoints at the Audience and Scoring Hive rows.
    private static final Pose RED_OUTSIDE_HIVE_AUDIENCE = new Pose(18.000, 57.234, 0);
    private static final Pose RED_INSIDE_HIVE_AUDIENCE = new Pose(30.000, 57.234, 0);
    private static final Pose RED_OUTSIDE_HIVE_SCORING = new Pose(18.000, 84.114, 0);
    private static final Pose RED_INSIDE_HIVE_SCORING = new Pose(30.000, 84.114, 0);
    private static final Pose BLUE_OUTSIDE_HIVE_AUDIENCE = new Pose(123.348, 57.234, Math.PI);
    private static final Pose BLUE_INSIDE_HIVE_AUDIENCE = new Pose(111.348, 57.234, Math.PI);
    private static final Pose BLUE_OUTSIDE_HIVE_SCORING = new Pose(123.348, 84.114, Math.PI);
    private static final Pose BLUE_INSIDE_HIVE_SCORING = new Pose(111.348, 84.114, Math.PI);

    // Stops outside the Hive base. These are not Cell-entry or scoring poses.
    private static final Pose RED_HIVE_AUDIENCE_SAFE_STOP = new Pose(31.000, 57.234, 0);
    private static final Pose RED_HIVE_SCORING_SAFE_STOP = new Pose(31.000, 84.114, 0);
    private static final Pose BLUE_HIVE_AUDIENCE_SAFE_STOP = new Pose(110.348, 57.234, Math.PI);
    private static final Pose BLUE_HIVE_SCORING_SAFE_STOP = new Pose(110.348, 84.114, Math.PI);

    // Explicit Audience and Scoring bypasses. Cross-field segments occur at
    // Y=37.000 or Y=104.348, outside the expanded Hive keep-out.
    private static final Pose RED_OUTSIDE_AUDIENCE_BYPASS = new Pose(18.000, 37.000, 0);
    private static final Pose RED_INSIDE_AUDIENCE_BYPASS = new Pose(30.000, 37.000, 0);
    private static final Pose RED_OUTSIDE_SCORING_BYPASS = new Pose(18.000, 104.348, 0);
    private static final Pose RED_INSIDE_SCORING_BYPASS = new Pose(30.000, 104.348, 0);
    private static final Pose BLUE_OUTSIDE_AUDIENCE_BYPASS = new Pose(123.348, 37.000, Math.PI);
    private static final Pose BLUE_INSIDE_AUDIENCE_BYPASS = new Pose(111.348, 37.000, Math.PI);
    private static final Pose BLUE_OUTSIDE_SCORING_BYPASS = new Pose(123.348, 104.348, Math.PI);
    private static final Pose BLUE_INSIDE_SCORING_BYPASS = new Pose(111.348, 104.348, Math.PI);

    // Lane waypoints at Flower rows. Flower order follows the Flower enum.
    private static final Pose[] RED_OUTSIDE_FLOWER_ROWS = {
            new Pose(18.000, 47.282, 0), new Pose(18.000, 122.348, 0),
            new Pose(18.000, 94.066, 0), new Pose(18.000, 19.000, 0)
    };
    private static final Pose[] RED_INSIDE_FLOWER_ROWS = {
            new Pose(30.000, 47.282, 0), new Pose(30.000, 122.348, 0),
            new Pose(30.000, 94.066, 0), new Pose(30.000, 19.000, 0)
    };
    private static final Pose[] BLUE_OUTSIDE_FLOWER_ROWS = {
            new Pose(123.348, 47.282, Math.PI), new Pose(123.348, 122.348, Math.PI),
            new Pose(123.348, 94.066, Math.PI), new Pose(123.348, 19.000, Math.PI)
    };
    private static final Pose[] BLUE_INSIDE_FLOWER_ROWS = {
            new Pose(111.348, 47.282, Math.PI), new Pose(111.348, 122.348, Math.PI),
            new Pose(111.348, 94.066, Math.PI), new Pose(111.348, 19.000, Math.PI)
    };

    // Physical Hive Cell centers, CAD-derived and projected into field coordinates.
    public static final FieldPoint RED_AUDIENCE_CELL_CENTER = new FieldPoint(57.924, 57.234);
    public static final FieldPoint RED_SCORING_CELL_CENTER = new FieldPoint(57.924, 84.114);
    public static final FieldPoint BLUE_AUDIENCE_CELL_CENTER = new FieldPoint(83.424, 57.234);
    public static final FieldPoint BLUE_SCORING_CELL_CENTER = new FieldPoint(83.424, 84.114);

    public static Pose start(boolean redAlliance, int rowIndex) {
        if (rowIndex < 0 || rowIndex >= 6) {
            throw new IllegalArgumentException("Start row must be 1 through 6.");
        }
        return (redAlliance ? RED_START_ROWS : BLUE_START_ROWS)[rowIndex];
    }

    public static Pose laneEntry(boolean redAlliance, Lane lane, int rowIndex) {
        if (rowIndex < 0 || rowIndex >= 6) {
            throw new IllegalArgumentException("Start row must be 1 through 6.");
        }
        if (redAlliance) {
            return (lane == Lane.INSIDE ? RED_INSIDE_LANE_ENTRY : RED_OUTSIDE_LANE_ENTRY)[rowIndex];
        }
        return (lane == Lane.INSIDE ? BLUE_INSIDE_LANE_ENTRY : BLUE_OUTSIDE_LANE_ENTRY)[rowIndex];
    }

    public static Pose hiveLane(boolean redAlliance, Lane lane, BypassSide side) {
        if (redAlliance) {
            if (lane == Lane.INSIDE) {
                return side == BypassSide.AUDIENCE ? RED_INSIDE_HIVE_AUDIENCE : RED_INSIDE_HIVE_SCORING;
            }
            return side == BypassSide.AUDIENCE ? RED_OUTSIDE_HIVE_AUDIENCE : RED_OUTSIDE_HIVE_SCORING;
        }
        if (lane == Lane.INSIDE) {
            return side == BypassSide.AUDIENCE ? BLUE_INSIDE_HIVE_AUDIENCE : BLUE_INSIDE_HIVE_SCORING;
        }
        return side == BypassSide.AUDIENCE ? BLUE_OUTSIDE_HIVE_AUDIENCE : BLUE_OUTSIDE_HIVE_SCORING;
    }

    public static Pose hiveSafeStop(boolean redAlliance, BypassSide side) {
        if (redAlliance) {
            return side == BypassSide.AUDIENCE
                    ? RED_HIVE_AUDIENCE_SAFE_STOP : RED_HIVE_SCORING_SAFE_STOP;
        }
        return side == BypassSide.AUDIENCE
                ? BLUE_HIVE_AUDIENCE_SAFE_STOP : BLUE_HIVE_SCORING_SAFE_STOP;
    }

    public static Pose bypass(boolean redAlliance, Lane lane, BypassSide side) {
        if (redAlliance) {
            if (lane == Lane.INSIDE) {
                return side == BypassSide.AUDIENCE
                        ? RED_INSIDE_AUDIENCE_BYPASS : RED_INSIDE_SCORING_BYPASS;
            }
            return side == BypassSide.AUDIENCE
                    ? RED_OUTSIDE_AUDIENCE_BYPASS : RED_OUTSIDE_SCORING_BYPASS;
        }
        if (lane == Lane.INSIDE) {
            return side == BypassSide.AUDIENCE
                    ? BLUE_INSIDE_AUDIENCE_BYPASS : BLUE_INSIDE_SCORING_BYPASS;
        }
        return side == BypassSide.AUDIENCE
                ? BLUE_OUTSIDE_AUDIENCE_BYPASS : BLUE_OUTSIDE_SCORING_BYPASS;
    }

    public static boolean crossesToOtherAllianceHalf(boolean redAlliance, Flower flower) {
        return (redAlliance && flower == Flower.BLUE_WALL)
                || (!redAlliance && flower == Flower.RED_WALL);
    }

    public static boolean flowerLaneIsRed(boolean robotIsRed, Flower flower) {
        if (flower == Flower.RED_WALL) return true;
        if (flower == Flower.BLUE_WALL) return false;
        return robotIsRed;
    }

    public static Pose flowerLane(boolean redLane, Lane lane, Flower flower) {
        int index = flower.ordinal();
        if (redLane) {
            return (lane == Lane.INSIDE ? RED_INSIDE_FLOWER_ROWS : RED_OUTSIDE_FLOWER_ROWS)[index];
        }
        return (lane == Lane.INSIDE ? BLUE_INSIDE_FLOWER_ROWS : BLUE_OUTSIDE_FLOWER_ROWS)[index];
    }
}
